                    {
                        "booking_ref": ref,
                        "source": "reference supplied by the contact",
                        "outcome": "no such booking in the operational record",
                    }
                )
                continue
            unresolved.append(
                "lookup of reference {} failed: {} {}".format(ref, exc.status, exc.error_code)
            )
            continue

